css:
.archsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b3242;
    background: linear-gradient(180deg, #f7f3ec 0%, #f1ece2 100%);
    border-radius: 18px;
}

.archsim-container * {
    box-sizing: border-box;
}

.archsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #14233f 0%, #1d3357 55%, #7c1d2e 130%);
    color: #f4efe6;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #0e1a30;
    box-shadow: 0 14px 36px rgba(20, 35, 63, 0.30);
}

.archsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fbf7ef;
}

.archsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e8b24c;
    background: rgba(232, 178, 76, 0.14);
    border: 1px solid rgba(232, 178, 76, 0.38);
    padding: 5px 14px;
    border-radius: 999px;
}

.archsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d8d0c2;
}

.archsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5b6275;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.archsim-period-counter #currentDay,
.archsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #7c1d2e;
}

.archsim-round-name {
    background: rgba(124, 29, 46, 0.10);
    color: #7c1d2e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.archsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a6515;
    background: rgba(232, 178, 76, 0.18);
    border: 1px solid rgba(232, 178, 76, 0.45);
    padding: 4px 12px;
    border-radius: 999px;
}

.archsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.archsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e4dccd;
    box-shadow: 0 6px 18px rgba(20, 35, 63, 0.08);
    border-top: 4px solid #1d3357;
}

.archsim-card-margin { border-top-color: #1f7a5c; }
.archsim-card-impact { border-top-color: #7c1d2e; }
.archsim-card-feas { border-top-color: #1d3357; }
.archsim-card-renew { border-top-color: #c0852a; }

.archsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a8576;
}

.archsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14233f;
    font-variant-numeric: tabular-nums;
}

.archsim-card-margin .archsim-value { color: #1f7a5c; }
.archsim-card-impact .archsim-value { color: #7c1d2e; }
.archsim-card-feas .archsim-value { color: #1d3357; }
.archsim-card-renew .archsim-value { color: #c0852a; }

.archsim-sublabel {
    font-size: 0.76rem;
    color: #8a8576;
    line-height: 1.35;
}

.archsim-margin-negative .archsim-value { color: #c33b2e; }
.archsim-margin-positive .archsim-value { color: #1f7a5c; }

.archsim-feas-low { border-top-color: #c33b2e; }
.archsim-feas-low .archsim-value { color: #c33b2e; }
.archsim-feas-high { border-top-color: #1f7a5c; }
.archsim-feas-high .archsim-value { color: #1f7a5c; }

.archsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14233f;
    border: 1px solid #0e1a30;
    color: #d8d0c2;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.archsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e8b24c;
}

.archsim-budget-over #budgetDisplay {
    color: #ff8a7a;
}

.archsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #7c1d2e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 35, 63, 0.08);
}

.archsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.archsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14233f;
    margin-bottom: 6px;
}

.archsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #444b5c;
}

.archsim-briefing-text strong { color: #7c1d2e; }
.archsim-briefing-text em { color: #8a6515; font-style: italic; }

.archsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e4dccd;
    box-shadow: 0 6px 18px rgba(20, 35, 63, 0.08);
}

.archsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14233f;
    border-bottom: 2px solid #efe7d8;
    padding-bottom: 8px;
}

.archsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3242;
    margin: 14px 0 6px;
}

.archsim-container select,
.archsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d6cdba;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf8f2;
    color: #2b3242;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.archsim-container select:focus,
.archsim-container input[type="number"]:focus {
    outline: none;
    border-color: #7c1d2e;
    box-shadow: 0 0 0 3px rgba(124, 29, 46, 0.14);
}

.archsim-container select option {
    background-color: #ffffff;
    color: #2b3242;
}

.archsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #7c1d2e;
}

.archsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5b6275;
    margin-top: 4px;
}

.archsim-range-readout span:last-child {
    color: #7c1d2e;
    font-weight: 800;
}

.archsim-hint {
    font-size: 0.8rem;
    color: #8a8576;
    margin-top: 4px;
    line-height: 1.4;
}

.archsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.archsim-container .btn-primary {
    background: linear-gradient(135deg, #7c1d2e 0%, #a8323f 100%);
    border: none;
    color: #fdf6ef;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(124, 29, 46, 0.32);
}

.archsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.archsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d6cdba;
    color: #5b6275;
    background: transparent;
}

.archsim-coach {
    background: linear-gradient(135deg, #14233f 0%, #20355a 100%);
    color: #e7e0d2;
    border: 1px solid #0e1a30;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 35, 63, 0.18);
}

.archsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e8b24c;
    margin-bottom: 8px;
}

.archsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.archsim-coach-body strong { color: #e8b24c; }
.archsim-coach-body em { color: #f0c878; font-style: italic; }

.archsim-history,
.archsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e4dccd;
    box-shadow: 0 6px 18px rgba(20, 35, 63, 0.08);
}

.archsim-history h3,
.archsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14233f;
}

.archsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2b3242;
}

.archsim-container table#usfHistoryTable th {
    background: #f4efe6;
    color: #7c1d2e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e4dccd;
}

.archsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efe7d8;
    color: #444b5c;
}

.archsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf6ee;
}

.archsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .archsim-container {
        padding: 14px;
    }
    .archsim-header h1 {
        font-size: 1.7rem;
    }
    .archsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .archsim-value {
        font-size: 2rem;
    }
    .archsim-clock {
        margin-left: 0;
    }
    .archsim-period-counter {
        font-size: 0.88rem;
    }
    .archsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .archsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.archsim-cm { background:#f7f5f0; color:#20222b; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.archsim-cm-head { text-align:center; border-bottom:1px solid #e2ddd0; padding-bottom:14px; margin-bottom:16px; }
.archsim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#6a6456; font-weight:700; }
.archsim-cm-scorewrap { margin:8px 0 2px; }
.archsim-cm-score { font-size:52px; font-weight:800; color:#7c1d2e; line-height:1; }
.archsim-cm-score-max { font-size:20px; color:#94907f; font-weight:600; }
.archsim-cm-grade { font-size:19px; font-weight:700; color:#20222b; margin-top:4px; }
.archsim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.archsim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.archsim-cm-met { background:#d7ead9; color:#1d5b34; }
.archsim-cm-fail { background:#f4dcd9; color:#8a2b2f; }
.archsim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.archsim-cm-metric { background:#efe9dd; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.archsim-cm-metric-val { font-size:22px; font-weight:800; color:#20222b; }
.archsim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#6a6456; margin-top:3px; }
.archsim-cm-insights { background:#efe9dd; border-radius:10px; padding:14px 18px; }
.archsim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#6a6456; font-weight:700; margin-bottom:8px; }
.archsim-cm-insights ul { margin:0; padding-left:18px; }
.archsim-cm-insights li { font-size:14px; line-height:1.5; color:#36332b; margin-bottom:7px; }

