(function() {
    'use strict';

    class ArchitectAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Program Architect`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Northline / Cascadia). Currency: CAD, shown as C$.
            this.BUDGET = 750000;            // CAD 750,000 fixed engagement price (no overage)
            this.PER_HEAD_CAP = 5000;        // CAD 5,000 all-in per participant
            this.BOUTIQUE = 540000;          // CAD 540,000 competing boutique quote
            this.TARGET_MARGIN = 0.22;       // Northline's 22% contribution margin
            this.LAUNCH_DAYS = 90;           // ~90-day launch window

            // Format menu: per-head cost (CAD), build days, behaviour-impact rating (0–10).
            this.FORMATS = {
                inperson: { cost: 6800, days: 120, impact: 8 },
                online:   { cost: 2400, days: 45,  impact: 3 },
                blended:  { cost: 4600, days: 80,  impact: 7 },
                sim:      { cost: 5200, days: 70,  impact: 6 }
            };
            this.REINFORCE = { none: 0, light: 400, full: 700 };

            // Concept truths (the modelled "right" path).
            this.TRUE_PROBLEM = `decision`;
            this.TRUE_METRIC = `speed`;
            this.TRUE_FORMAT = `blended`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    margin: 0,           // CAD engagement margin vs cost (computed in R2/R4)
                    impact: 18,          // provable behaviour & business-result case (0–100)
                    feas: 25,            // fits per-head budget AND the 90-day launch (0–100)
                    renew: 30,           // confidence Cascadia renews the 1.6M account (0–100)
                    perHead: 0,          // CAD per-participant design cost committed
                    cohort: 150,         // participants served
                    revenue: this.BUDGET,
                    overBudget: false,
                    cantLaunch: false,
                    discounted: false,
                    overClaimed: false,
                    marginHistory: [0],
                    impactHistory: [18],
                    feasHistory: [25],
                    renewHistory: [30],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    problem: `content`,
                    metric: `happy`,
                    discovery: `skip`,
                    r1conviction: 50,
                    format: `inperson`,
                    reinforce: `none`,
                    scope: 40,
                    cohort: 150,
                    levels: `l1`,
                    baseline: `none`,
                    headline: `overclaim`,
                    owner: `endonly`,
                    price: `match`,
                    pitch: `reputation`,
                    risk: `hide`,
                    r4conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const pr = document.getElementById(`problemInput`);
                const me = document.getElementById(`metricInput`);
                const di = document.getElementById(`discoveryInput`);
                const cv = document.getElementById(`r1convictionInput`);
                if (pr) decisions.problem = pr.value;
                if (me) decisions.metric = me.value;
                if (di) decisions.discovery = di.value;
                if (cv) decisions.r1conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.r1conviction) || decisions.r1conviction < 0 || decisions.r1conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            } else if (round === 2) {
                const fm = document.getElementById(`formatInput`);
                const re = document.getElementById(`reinforceInput`);
                const sc = document.getElementById(`scopeInput`);
                const co = document.getElementById(`cohortInput`);
                if (fm) decisions.format = fm.value;
                if (re) decisions.reinforce = re.value;
                if (sc) decisions.scope = parseInt(sc.value, 10);
                if (co) decisions.cohort = parseInt(co.value, 10);
                if (!Number.isFinite(decisions.scope) || decisions.scope < 0 || decisions.scope > 100) {
                    warn(`warn_scope_range`); return false;
                }
                if (!Number.isFinite(decisions.cohort) || decisions.cohort <= 0) {
                    warn(`warn_cohort_value`); return false;
                }
            } else if (round === 3) {
                const lv = document.getElementById(`levelsInput`);
                const ba = document.getElementById(`baselineInput`);
                const hd = document.getElementById(`headlineInput`);
                const ow = document.getElementById(`ownerInput`);
                if (lv) decisions.levels = lv.value;
                if (ba) decisions.baseline = ba.value;
                if (hd) decisions.headline = hd.value;
                if (ow) decisions.owner = ow.value;
            } else if (round === 4) {
                const pc = document.getElementById(`priceInput`);
                const pi = document.getElementById(`pitchInput`);
                const rk = document.getElementById(`riskInput`);
                const cv = document.getElementById(`r4convictionInput`);
                if (pc) decisions.price = pc.value;
                if (pi) decisions.pitch = pi.value;
                if (rk) decisions.risk = rk.value;
                if (cv) decisions.r4conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.r4conviction) || decisions.r4conviction < 0 || decisions.r4conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let impactDelta = 0, feasDelta = 0, renewDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the REAL business need (Common Error 1: sell content, don't diagnose).
                switch (d.problem) {
                    case `decision`: impactDelta += 12; renewDelta += 8; coachKey = `coach_r1_decision`; break;
                    case `engagement`: impactDelta += 2; renewDelta += 1; coachKey = `coach_r1_engagement`; break;
                    case `skills`: impactDelta -= 2; coachKey = `coach_r1_skills`; break;
                    case `content`: impactDelta -= 6; renewDelta -= 6; coachKey = `coach_r1_content`; break;
                }

                // Pick the metric the CEO would actually accept (sets up Round 3).
                switch (d.metric) {
                    case `speed`: impactDelta += 8; renewDelta += 4; if (d.problem === `decision`) coachKey = `coach_r1_sharp`; break;
                    case `knowledge`: impactDelta += 1; break;
                    case `completion`: impactDelta -= 2; renewDelta -= 2; break;
                    case `happy`: impactDelta -= 6; renewDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r1_happy`; break;
                }

                // Use the second discovery call to diagnose, not to confirm.
                switch (d.discovery) {
                    case `diagnose`: impactDelta += 6; renewDelta += 4; break;
                    case `confirm`: impactDelta += 1; break;
                    case `skip`: impactDelta -= 4; renewDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r1_skip`; break;
                }

                if (d.r1conviction >= 60) { impactDelta += 4; renewDelta += 3; }
                else if (d.r1conviction <= 25) { impactDelta -= 4; renewDelta -= 3; coachKey = `coach_r1_lowconviction`; }

                summaryKey = (d.problem === `decision` && d.metric === `speed`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the format under the budget AND the deadline (Common Errors 2 & 3).
                const fmt = this.FORMATS[d.format] || this.FORMATS.blended;
                const reinforceCost = this.REINFORCE[d.reinforce] || 0;
                ds.cohort = d.cohort;

                // Reuse buys down build time and a slice of per-head cost.
                const reuse = d.scope / 100;
                const perHead = Math.round((fmt.cost * (1 - 0.18 * reuse)) + reinforceCost);
                const buildDays = Math.round(fmt.days * (1 - 0.30 * reuse));
                ds.perHead = perHead;

                // Resource accounting: revenue scales with cohort served; cost is per-head × cohort.
                ds.revenue = this.BUDGET; // fixed engagement price set at brief; price lever is R4
                const totalCost = perHead * d.cohort;
                ds.margin = Math.round(ds.revenue - totalCost);

                // Budget feasibility — CAD 5,000/head is the hard ceiling (Common Error 3).
                if (perHead > this.PER_HEAD_CAP) {
                    ds.overBudget = true;
                    const over = perHead - this.PER_HEAD_CAP;
                    feasDelta -= 12 + Math.min(14, Math.round(over / 130));
                    renewDelta -= 6;
                    coachKey = `coach_r2_overbudget`;
                } else {
                    ds.overBudget = false;
                    feasDelta += 8;
                }

                // Time feasibility — must launch within 90 days (Common Error 2).
                if (buildDays > this.LAUNCH_DAYS) {
                    ds.cantLaunch = true;
                    feasDelta -= 10 + Math.min(12, Math.round((buildDays - this.LAUNCH_DAYS) / 4));
                    renewDelta -= 5;
                    if (coachKey === `coach_default`) coachKey = `coach_r2_cantlaunch`;
                } else {
                    ds.cantLaunch = false;
                    feasDelta += 8;
                }

                // Behaviour-change richness of the format drives the impact case.
                impactDelta += (fmt.impact - 5) * 3;
                if (d.reinforce === `full`) { impactDelta += 6; renewDelta += 3; }
                else if (d.reinforce === `light`) { impactDelta += 2; }

                // Cohort trimming protects the budget but reaches fewer managers.
                if (d.cohort < 150) {
                    renewDelta -= Math.round((150 - d.cohort) / 12);
                    if (!ds.overBudget && !ds.cantLaunch && coachKey === `coach_default`) coachKey = `coach_r2_cohort`;
                }

                // Over-reliance on off-the-shelf content won't change Cascadia's specific behaviour.
                if (reuse >= 0.85) { impactDelta -= 5; coachKey = `coach_r2_offshelf`; }

                if (coachKey === `coach_default`) {
                    coachKey = (d.format === `blended`) ? `coach_r2_blended` : `coach_r2_feasible`;
                }

                summaryKey = (!ds.overBudget && !ds.cantLaunch && fmt.impact >= 6) ? `sum_r2_good` :
                             (ds.overBudget ? `sum_r2_overbudget` : (ds.cantLaunch ? `sum_r2_cantlaunch` : `sum_r2_weak`));
            } else if (round === 3) {
                // Build the measurement architecture (Common Error 4: measure Level 1 only).
                switch (d.levels) {
                    case `l4`: impactDelta += 14; renewDelta += 8; coachKey = `coach_r3_l4`; break;
                    case `l3`: impactDelta += 8; renewDelta += 4; break;
                    case `l2`: impactDelta += 2; break;
                    case `l1`: impactDelta -= 8; renewDelta -= 6; coachKey = `coach_r3_l1`; break;
                }

                // Pre-program baseline — the discipline the prior program skipped.
                switch (d.baseline) {
                    case `before`: impactDelta += 10; renewDelta += 5; break;
                    case `after`: impactDelta += 1; break;
                    case `none`: impactDelta -= 8; renewDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r3_nobaseline`; break;
                }

                // Headline metric & attribution (decision-tree error 6: over-claim).
                switch (d.headline) {
                    case `defensible`: impactDelta += 10; renewDelta += 6; if (d.levels === `l4` && d.baseline === `before`) coachKey = `coach_r3_sharp`; break;
                    case `vague`: impactDelta -= 3; renewDelta -= 2; break;
                    case `overclaim`: ds.overClaimed = true; impactDelta -= 4; renewDelta -= 6; coachKey = `coach_r3_overclaim`; break;
                }

                // Read-out cadence and shared data ownership.
                if (d.owner === `quarterly`) { impactDelta += 4; renewDelta += 4; }
                else { renewDelta -= 2; }

                summaryKey = (d.levels === `l4` && d.baseline === `before` && d.headline === `defensible`) ? `sum_r3_good` :
                             (ds.overClaimed ? `sum_r3_overclaim` : `sum_r3_weak`);
            } else if (round === 4) {
                // Pitch & commit — defend the premium on outcomes, not price (Common Error 5).
                switch (d.price) {
                    case `hold`:
                        renewDelta += 6;
                        ds.discounted = false;
                        // Margin holds at the full engagement price.
                        ds.revenue = this.BUDGET;
                        coachKey = `coach_r4_hold`;
                        break;
                    case `split`:
                        ds.discounted = true;
                        ds.revenue = 640000;
                        renewDelta += 1;
                        coachKey = `coach_r4_split`;
                        break;
                    case `match`:
                        ds.discounted = true;
                        ds.revenue = this.BOUTIQUE;
                        renewDelta -= 4;
                        coachKey = `coach_r4_match`;
                        break;
                }
                // Recompute margin against the (possibly discounted) revenue and committed cost.
                ds.margin = Math.round(ds.revenue - ds.perHead * ds.cohort);

                // Lead message of the pitch.
                switch (d.pitch) {
                    case `outcome`: impactDelta += 8; renewDelta += 8; if (d.price === `hold`) coachKey = `coach_r4_outcome`; break;
                    case `content`: renewDelta += 1; break;
                    case `reputation`: renewDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r4_reputation`; break;
                }

                // Name the biggest delivery risk + mitigation.
                switch (d.risk) {
                    case `attribution`: impactDelta += 5; renewDelta += 5; break;
                    case `faculty`: renewDelta += 3; break;
                    case `hide`: renewDelta -= 5; if (coachKey === `coach_default`) coachKey = `coach_r4_hide`; break;
                }

                if (d.r4conviction >= 60) { renewDelta += 5; }
                else if (d.r4conviction <= 25) { renewDelta -= 5; }

                summaryKey = (d.price === `hold` && d.pitch === `outcome`) ? `sum_r4_good` :
                             (ds.discounted ? `sum_r4_discount` : `sum_r4_weak`);
            }

            // Per-participant design committed (metered display; cap is CAD 5,000).
            // Apply deltas, clamped 0–100 (margin is CAD, unbounded but realistic).
            ds.impact = Math.max(0, Math.min(100, Math.round(ds.impact + impactDelta)));
            ds.feas = Math.max(0, Math.min(100, Math.round(ds.feas + feasDelta)));
            ds.renew = Math.max(0, Math.min(100, Math.round(ds.renew + renewDelta)));

            ds.marginHistory.push(ds.margin);
            ds.impactHistory.push(ds.impact);
            ds.feasHistory.push(ds.feas);
            ds.renewHistory.push(ds.renew);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                margin: ds.margin,
                impact: ds.impact,
                impactDelta: Math.round(impactDelta),
                feas: ds.feas,
                feasDelta: Math.round(feasDelta),
                renew: ds.renew,
                renewDelta: Math.round(renewDelta),
                perHead: ds.perHead,
                overBudget: ds.overBudget,
                cantLaunch: ds.cantLaunch,
                discounted: ds.discounted,
                overClaimed: ds.overClaimed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtCAD(v) {
            // Consistent CAD notation: "C$750,000" in English, "750.000 CAD" in Spanish
            // (thousands separator; never a bare $ that could read as USD).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const neg = v < 0;
            const abs = Math.abs(Math.round(v));
            if (lang === `es`) {
                const grouped = abs.toString().replace(/\B(?=(\d{3})+(?!\d))/g, `.`);
                return `${neg ? `-` : ``}${grouped} CAD`;
            }
            const grouped = abs.toString().replace(/\B(?=(\d{3})+(?!\d))/g, `,`);
            return `${neg ? `-` : ``}C$${grouped}`;
        }

