        _composite(ds) {
            // v1.0.0 composite formula, verbatim — single source of truth.
            const margin = ds.margin;
            const impact = Math.round(ds.impact);
            const feas = Math.round(ds.feas);
            const renew = Math.round(ds.renew);
            const marginScore = Math.max(-20, Math.min(20, Math.round((margin / (this.BUDGET * this.TARGET_MARGIN)) * 20)));
            return Math.round(impact * 0.34 + feas * 0.26 + renew * 0.26 + (marginScore + 20) * 0.35);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const margin = ds.margin;
            const impact = Math.round(ds.impact);
            const feas = Math.round(ds.feas);
            const renew = Math.round(ds.renew);

            // Composite: impact case, feasibility, renewal confidence, plus a margin bonus
            // (normalised: full target margin ≈ CAD 165,000; worth up to ~20 points).
            const composite = this._composite(ds);

            const profitable = margin > 0;
            const provable = impact >= 60;
            const feasible = feas >= 60;
            const renewing = renew >= 60;

            let performanceKey = `grade_lost`;
            if (profitable && provable && feasible && composite >= 75) performanceKey = `grade_architect`;
            else if (provable && feasible && renewing) performanceKey = `grade_renewal`;
            else if (!feasible && (ds.overBudget || ds.cantLaunch)) performanceKey = `grade_undeliverable`;
            else if (ds.discounted && margin <= 0) performanceKey = `grade_margin`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const met = profitable && provable && feasible && composite >= 75;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (profitable && provable && feasible) insights.push(window.mySimulation.t(`insight_architect`));
            else if (ds.overBudget || ds.cantLaunch) insights.push(window.mySimulation.t(`insight_undeliverable`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (margin <= 0) insights.push(window.mySimulation.t(`insight_margin_negative`));
            else if (margin >= this.BUDGET * this.TARGET_MARGIN) insights.push(window.mySimulation.t(`insight_margin_strong`));
            if (ds.overClaimed) insights.push(window.mySimulation.t(`insight_overclaim`));
            if (impact < 45) insights.push(window.mySimulation.t(`insight_unprovable`));
            if (ds.discounted) insights.push(window.mySimulation.t(`insight_discounted`));
            if (renew >= 70 && impact >= 65) insights.push(window.mySimulation.t(`insight_trusted`));

            return {
                margin: margin,
                impact: impact,
                feas: feas,
                renew: renew,
                profitable: profitable,
                provable: provable,
                feasible: feasible,
                renewing: renewing,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                overBudget: !!ds.overBudget,
                cantLaunch: !!ds.cantLaunch,
                discounted: !!ds.discounted,
                overClaimed: !!ds.overClaimed,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="archsim-cm-badge ` + (s.met ? `archsim-cm-met` : `archsim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.overBudget) badges.push(`<span class="archsim-cm-badge archsim-cm-fail">` + t(`cm_fail_budget`) + `</span>`);
            if (s.cantLaunch) badges.push(`<span class="archsim-cm-badge archsim-cm-fail">` + t(`cm_fail_launch`) + `</span>`);
            if (s.discounted && (s.margin != null && s.margin <= 0)) badges.push(`<span class="archsim-cm-badge archsim-cm-fail">` + t(`cm_fail_margin`) + `</span>`);
            if (s.overClaimed) badges.push(`<span class="archsim-cm-badge archsim-cm-fail">` + t(`cm_fail_overclaim`) + `</span>`);
            const kpi = (label, val) => `<div class="archsim-cm-metric"><div class="archsim-cm-metric-val">` + val + `</div><div class="archsim-cm-metric-lbl">` + label + `</div></div>`;
            const mg = (s.margin != null) ? (this._fmtCAD ? this._fmtCAD(s.margin) : (`CAD ` + s.margin)) : ``;
            const kpis = kpi(t(`cm_margin`), mg)
                + kpi(t(`cm_impact`), (s.impact != null ? Math.round(s.impact) : 0))
                + kpi(t(`cm_feas`), (s.feas != null ? Math.round(s.feas) : 0))
                + kpi(t(`cm_renew`), (s.renew != null ? Math.round(s.renew) : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="archsim-cm">`
                + `<div class="archsim-cm-head"><div class="archsim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="archsim-cm-scorewrap"><span class="archsim-cm-score">` + score + `</span><span class="archsim-cm-score-max">/100</span></div>`
                + `<div class="archsim-cm-grade">` + grade + `</div>`
                + `<div class="archsim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="archsim-cm-metrics">` + kpis + `</div>`
                + `<div class="archsim-cm-insights"><div class="archsim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
