            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.cantLaunch) return window.mySimulation.t(`hint_cantlaunch`);
            if (ds.overClaimed) return window.mySimulation.t(`hint_overclaim`);
            if (ds.discounted && ds.margin <= 0) return window.mySimulation.t(`hint_discount`);
            if (state.currentPeriod >= 3 && ds.impact < 45) return window.mySimulation.t(`hint_impact`);
            if (ds.impact >= 65 && ds.feas >= 60 && ds.renew >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

